267.sql:
SELECT bond_type
FROM bond
WHERE molecule_id BETWEEN 'TR000' AND 'TR050';

419.sql:
SELECT COUNT(*) AS answer
FROM cards
WHERE borderColor = 'borderless' AND edhrecRank > 12000;

625.sql:
SELECT COUNT(*) AS answer
FROM users
WHERE Location LIKE '%New York%';

882.sql:
SELECT MIN(year) AS answer
FROM races
WHERE name = 'Singapore Grand Prix';

996.sql:
SELECT COUNT(*) / 11 AS annual_average
FROM races
WHERE date BETWEEN '2000-01-01' AND '2010-12-31';

1035.sql:
SELECT DISTINCT `team_fifa_api_id`
FROM Team_Attributes
WHERE `buildUpPlaySpeed` > 50 AND `buildUpPlaySpeed` < 60;

1213.sql:
SELECT `ID` AS answer
FROM (
    SELECT DISTINCT `ID`
    FROM (
        SELECT p.`ID`
        FROM Patient AS p
        INNER JOIN Laboratory AS l ON p.`ID` = l.`ID`
        WHERE p.`Birthday` = '1982-04-01' AND l.`ALP` < 300
    ) AS c_rows
) AS t_distinct;

1393.sql:
SELECT first_name, last_name, email
FROM member
WHERE position = 'Secretary';
